# 一个能跑通的最小表达式解释器：词法 -> 语法 -> 求值
import re

TOKEN = re.compile(r'\s*(?:(?P<num>\d+)|(?P<op>[+*()]))')

def tokens(src):
    result, pos = [], 0
    while pos < len(src):
        m = TOKEN.match(src, pos)
        if not m:
            raise SyntaxError(f'无法识别的字符: {src[pos]!r} 位置 {pos}')
        pos = m.end()
        if m.lastgroup == 'num':
            result.append(('num', int(m.group('num'))))
        elif m.lastgroup:
            result.append((m.group('op'), None))
    return result

def parse(ts):
    def atom(i):
        kind, value = ts[i]
        if kind == 'num':
            return value, i + 1
        if kind == '(':
            node, i = expr(i + 1)
            assert ts[i][0] == ')', f'缺少右括号，位置 {i}'
            return node, i + 1
        raise SyntaxError(f'非法的记号 {kind}，位置 {i}')
    def term(i):
        node, i = atom(i)
        while i < len(ts) and ts[i][0] == '*':
            right, i = atom(i + 1)
            node = node * right
        return node, i
    def expr(i):
        node, i = term(i)
        while i < len(ts) and ts[i][0] == '+':
            right, i = term(i + 1)
            node = node + right
        return node, i
    value, index = expr(0)
    if index != len(ts):
        raise SyntaxError(f'多余的记号，位置 {index}')
    return value

print(tokens('1 + 2 * (3 + 4)'))
print('结果:', parse(tokens('1 + 2 * (3 + 4)')))

